head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

scwin.fn_openPopup = function(a){
	requires("uiplugin.popup");

	var rowJSON = { 
	    "poupObjectNm": "popup1" 
	};
	//popup에 넘길 data객체. 
	var dataObj={ 
	    type : "json",      // 데이터 타입. "xml","string","json","array" 
	    data : rowJSON,     // 전달 데이터 객체. 
	    name : "paramTest"     // 변수명. popup에서 $w.getParameter( "paramTest" )로 깨내올 수 있다. 
	};
	var options = { 
		id : "popup1", 
		type : "browserPopup",    //
		width: 300 + "px", 
		height: 300 + "px", 

		top: 100 + "px", 
		left: 100 + "px", 


		modal : true, 
		onlyParam : true,

		style : "", 

		resizable : true, 
		status : false, 
		menubar : false, 
		scrollbars : false, 
		title : false, 
		useMaximize : true,

		dataObject : dataObj
	};
	$p.openPopup("",  options );
};
	scwin.trigger3_onclick = function(e) {
		scwin.fn_openPopup("bbb");
	};
